import React from 'react';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"


const MoodJournal = () => {
  return (
      <div className="flex flex-col min-h-screen">
        <div className="navbar bg-base-100">
          <div className="navbar-start"></div>
          <h1 className="navbar-center text-5xl">Mood Journal</h1>
          <div className="navbar-end"></div>
        </div>
        <div className="moodSliderComponent flex flex-row ">
          <div className='mood-card'>
            <Card>
              <CardHeader>
                <CardTitle>How&apos;s your mood?</CardTitle>
              </CardHeader>
              <CardContent>
                <p>Card Content</p>
              </CardContent>
            </Card>
          </div>
          <div className='energy-card'>
            <Card>
              <CardHeader>
                <CardTitle>How energetic do you feel?</CardTitle>
              </CardHeader>
              <CardContent>
                <p>Card Content</p>
              </CardContent>
            </Card>
          </div>
          <div className='stress-card'>
            <Card>
              <CardHeader>
                <CardTitle>How stressed do you feel?</CardTitle>
              </CardHeader>
              <CardContent>
                <p>Card Content</p>
              </CardContent>
            </Card>
          </div>
        </div>
        <div className='journal-section'>
          <Card>
            <CardHeader>
              <CardTitle>Today&apos;s Prompt:</CardTitle>
              <CardDescription>What&apos;s one thing you would have done differently today?</CardDescription>
            </CardHeader>
            <CardContent>
              <p>Card Content</p>
            </CardContent>
          </Card>
        </div>
      </div>
    );
}

export default MoodJournal;